import MenuItem from '@mui/material/MenuItem';
import Box from '@mui/material/Box';
import { GridToolbarExportContainer } from '@mui/x-data-grid-premium';
import { GridOn, Code, Language, TableChart, DataObject as DataObjectIcon } from '@mui/icons-material';

// Helper to convert default sort string to array
export const convertDefaultSort = (defaultSort, constants, sortRegex) => {
    if (typeof defaultSort !== constants.string) return [];
    return defaultSort.split(',').flatMap(sortField => {
        sortRegex.lastIndex = 0;
        const sortInfo = sortRegex.exec(sortField);
        if (!sortInfo) return [];
        const [, field, direction = 'ASC'] = sortInfo;
        return [{ field: field.trim(), sort: direction.trim().toLowerCase() }];
    });
};

// Export menu item component (internal use only — used by CustomExportButton below)
const ExportMenuItem = ({ tTranslate, tOpts, handleExport, contentType, type, isPivotExport = false, exportKey, icon }) => (
    <MenuItem
        onClick={handleExport}
        data-type={type}
        data-content-type={contentType}
        data-is-pivot-export={isPivotExport}
        data-export-key={exportKey}
    >
        <Box className="grid-icons" sx={{ pointerEvents: 'none', marginTop: 1 }}>{icon}</Box>
        {tTranslate(type, tOpts)}
    </MenuItem>
);

// Custom export button component
export const CustomExportButton = ({ exportFormats, customExportOptions, isStaticDataMode = false, ...props }) => {
    const exportItems = [
        exportFormats.csv !== false && <ExportMenuItem key="csv" {...props} icon={<GridOn fontSize="small" />} type="CSV" contentType="text/csv" exportKey="csvExport" />,
        exportFormats.excel !== false && <ExportMenuItem key="excel" {...props} icon={<TableChart fontSize="small" />} type="Excel" contentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" exportKey="excelExport" />,
        !isStaticDataMode && props.showPivotExportBtn && <ExportMenuItem key="pivot" {...props} icon={<TableChart fontSize="small" />} type="Excel With Pivot" contentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" isPivotExport={true} exportKey="pivotExport" />,
        !isStaticDataMode && exportFormats.xml !== false && <ExportMenuItem key="xml" {...props} icon={<Code fontSize="small" />} type="XML" contentType="text/xml" exportKey="xmlExport" />,
        !isStaticDataMode && exportFormats.html !== false && <ExportMenuItem key="html" {...props} icon={<Language fontSize="small" />} type="HTML" contentType="text/html" exportKey="htmlExport" />,
        !isStaticDataMode && exportFormats.json !== false && <ExportMenuItem key="json" {...props} icon={<DataObjectIcon fontSize="small" />} type="JSON" contentType="application/json" exportKey="jsonExport" />,
        !isStaticDataMode && Array.isArray(customExportOptions) && customExportOptions.map((item, index) => (
            <ExportMenuItem
                key={item.key || index}
                {...props}
                icon={item.icon || <TableChart fontSize="small" />}
                type={item.label || 'Excel'}
                exportKey={item.key}
                contentType={item.contentType || "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}
                handleExport={item.handleExport || props.handleExport}
            />
        ))
    ].flat().filter(Boolean);

    if (exportItems.length === 0) return null;

    return (
        <GridToolbarExportContainer {...props}>
            {exportItems}
        </GridToolbarExportContainer>
    );
};

// Get default operator based on column type
export const getDefaultOperator = (type, customOperator) => {
    if (customOperator) return customOperator;
    switch (type) {
        case 'string':
            return 'startsWith';
        case 'number':
            return '=';
        case 'date':
        case 'dateTime':
            return 'is';
        case 'boolean':
            return 'is';
        case 'select':
        case 'lookup':
            return 'isAnyOf';
        default:
            return 'startsWith';
    }
};

// Shallow props comparison
export const areEqual = (prevProps = {}, nextProps = {}) => {
    let equal = true;
    for (const o in prevProps) {
        if (prevProps[o] !== nextProps[o]) {
            equal = false;
        }
    }
    for (const o in nextProps) {
        if (!(o in prevProps)) {
            equal = false;
        }
    }
    return equal;
};

/**
 * Height for a split panel being dragged, clamped so neither side can be dragged out of existence.
 * `delta` is the pixels the handle has moved since the drag started - negative is upwards, which
 * grows the panel, so it subtracts.
 *
 * The parent's floor wins when the container is too short to honour both: the panel gets squeezed to
 * its own minimum rather than the clamp inverting and jumping the handle.
 */
export const clampSplitHeight = ({ startHeight, delta, containerHeight, minPanelHeight, minSiblingHeight }) => {
    const maxHeight = Math.max(containerHeight - minSiblingHeight, minPanelHeight);
    return Math.min(Math.max(startHeight - delta, minPanelHeight), maxHeight);
};
