import { useFormik } from "formik";
import { useState, useEffect, useMemo, useCallback } from "react";
import {
  getRecord,
  saveRecord,
  deleteRecord
} from "../Grid/crud-helper";
import Button from "@mui/material/Button";
import Paper from "@mui/material/Paper";
import Stack from "@mui/material/Stack";
import Divider from "@mui/material/Divider";
import Tooltip from "@mui/material/Tooltip";
import CircularProgress from "@mui/material/CircularProgress";
import Box from "@mui/material/Box";
import FormLayout from "./field-mapper";
import { useSnackbar } from "../SnackBar";
import { DialogComponent } from "../Dialog";
import { useStateContext, useRouter } from "../useRouter/StateProvider";
import { LIST_STATE_PARAM, currentSearchParams } from "../Grid/listState";
import PageTitle from "../PageTitle";
import utils, { getPermissions } from "../utils";
import Relations from "./relations";
import { useModelTranslation } from "../../hooks/useModelTranslation";
import { ERROR_CODES } from "../../errors";
import { ActiveStepContext } from "./context";
const defaultFieldConfigs = {};
const DEFAULT_RELATION_FILTERS = {};
const DEFAULT_PERMISSIONS = {};
const DEFAULT_BASE_SAVE_DATA = {};
const consts = {
  object: "object",
  function: "function",
  baseData: "baseData",
  string: "string",
  create: "Create",
  copy: "Copy",
  edit: "Edit",
  number: "number",
  loadIdIndex: 1,
  editIdIndex: 0
};

const Form = ({
  model,
  api,
  models,
  relationFilters = DEFAULT_RELATION_FILTERS,
  permissions = DEFAULT_PERMISSIONS,
  Layout = FormLayout,
  baseSaveData = DEFAULT_BASE_SAVE_DATA,
  sx,
  readOnly,
  beforeSubmit,
  deletePromptText,
  detailPanelId = null, // Grid Row Detail Panel Id
  onCancel,
  onSaveSuccess
}) => {
  const formTitle = model.formTitle || model.title;
  const { translate, tOpts, tTranslate } = useModelTranslation(model);
  const { navigate, getParams, useParams, pathname } = useRouter();
  const { relations = [] } = model;
  const { stateData, buildUrl, setPageTitle } = useStateContext();
  const params = useParams() || getParams;
  const { id: idWithOptions = "" } = params;
  const id = detailPanelId || idWithOptions.split("-")[consts.editIdIndex];
  const searchParams = new URLSearchParams(window.location.search);
  const baseDataFromParams = searchParams.has(consts.baseData) && searchParams.get(consts.baseData);
  if (baseDataFromParams) {
    const parsedData = JSON.parse(baseDataFromParams);
    if (typeof parsedData === consts.object && parsedData !== null) {
      baseSaveData = { ...baseSaveData, ...parsedData };
    }
  }
  const [isLoading, setIsLoading] = useState(true);
  const [data, setData] = useState({});
  const [lookups, setLookups] = useState({});
  const [isDeleting, setIsDeleting] = useState(false);
  const snackbar = useSnackbar();
  const [activeStep, setActiveStep] = useState(0);
  const activeStepContextValue = useMemo(() => ({ activeStep, setActiveStep }), [activeStep, setActiveStep]);
  const [isDiscardDialogOpen, setIsDiscardDialogOpen] = useState(false);
  const [deleteError, setDeleteError] = useState(null);
  const [errorMessage, setErrorMessage] = useState("");
  const userData = stateData.userData || {};
  const fieldConfigs = typeof model.applyFieldConfig === consts.function
    ? model.applyFieldConfig({ data, lookups, userData })
    : defaultFieldConfigs;
  const gridApi = buildUrl(model.api);
  // Determine mode from URL pattern: "0-{id}" indicates copy mode
  const mode = idWithOptions.includes('-') && idWithOptions.split('-')[0] === '0' ? 'copy' : '';
  const userDefinedPermissions = {
    add: true,
    edit: true,
    delete: true,
    ...model.permissions,
    ...permissions
  };
  const { canAdd, canEdit, canDelete } = getPermissions({
    userData,
    model,
    userDefinedPermissions
  });
  const canCopy = canAdd && Boolean({ ...model.permissions, ...permissions }.copy);
  const { hideBreadcrumb = false, navigateBack, actions: actionsMode = 'grid' } = model;
  const showFormActions = actionsMode === 'form' || actionsMode === 'both';
  const recordEditable = !("canEdit" in data) || data.canEdit;

  const handleNavigation = useCallback(() => {
    let navigatePath;
    switch (typeof navigateBack) {
      case consts.function:
        navigatePath = navigateBack({ params, searchParams: currentSearchParams(), data });
        break;
      case consts.number:
      case consts.string:
        navigatePath = navigateBack;
        break;
      default: {
        navigatePath = pathname.substring(0, pathname.lastIndexOf("/"));
        // Carries the list's ?ls= snapshot id back so the grid restores its filters/sort/
        // page/grouping/selection instead of resetting - see Grid/listState.js.
        const listStateId = currentSearchParams().get(LIST_STATE_PARAM);
        if (listStateId) {
          navigatePath += `?${LIST_STATE_PARAM}=${encodeURIComponent(listStateId)}`;
        }
        break;
      }
    }
    navigate(navigatePath);
  }, [navigateBack, navigate, params, data, pathname]);

  const isNew = useMemo(() => utils.emptyIdValues.includes(id), [id]);

  const initialValues = useMemo(() => isNew
    ? { ...model.initialValues, ...data, ...baseSaveData }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- id kept as a dep so a route change forces recompute even though isNew already derives from it
    : { ...baseSaveData, ...model.initialValues, ...data }, [model.initialValues, data, id, baseSaveData, isNew]);

  const formApi = api || gridApi;
  const idToLoad = useMemo(() => {
    if (detailPanelId) {
      return detailPanelId;
    }
    const options = idWithOptions.split("-");
    return options.length > 1 ? options[consts.loadIdIndex] : id;
  }, [detailPanelId, idWithOptions, id]);
  const loadRecord = useCallback(async () => {
    setIsLoading(true);
    try {
      const data = await getRecord({
        api: formApi,
        model,
        id: idToLoad,
      });
      setActiveRecord(data);
    } catch (error) {
      errorOnLoad(error);
    } finally {
      setIsLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- errorOnLoad/setActiveRecord deliberately excluded: including them recreates loadRecord on every load (both depend transitively on `data`), retriggering the load effect and causing an infinite reload loop. idWithOptions is included on top of idToLoad so switching between edit and copy of the same record (idToLoad stays the same, only the "0-" prefix changes) still rebuilds the closure that isCopy is computed from.
  }, [formApi, model, idToLoad, idWithOptions]);
  
  useEffect(() => {
    loadRecord();
  }, [id, idToLoad, model, formApi, loadRecord]);

  const validationSchema = useMemo(
    () => model.getValidationSchema({ id, tTranslate, tOpts }),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- translate isn't read directly but its change must trigger recompute
    [id, model, translate, tOpts, tTranslate]
  );

  const formik = useFormik({
    enableReinitialize: true,
    initialValues,
    validationSchema: validationSchema,
    validateOnBlur: model?.validateOnBlur ?? false,
    onSubmit: async (values, { resetForm }) => {
      Object.keys(values).forEach(key => {
        if (typeof values[key] === consts.string) {
          values[key] = values[key].trim();
        }
      });
      setIsLoading(true);
      saveRecord({
        id,
        api: gridApi,
        values: values,
        model
      })
        .then((success) => {
          if (!success) return;
          if (model.reloadOnSave) {
            return window.location.reload();
          }
          if (typeof onSaveSuccess === consts.function) {
            onSaveSuccess();
          }
          const message = success.info ? success.info : `Record ${id === 0 ? "Added" : "Updated"} Successfully.`;
          snackbar.showMessage(tTranslate(message, tOpts));
          /**
          * Handle navigation after form operations
          * By default, the form navigates back to the grid after save/cancel operations.
          * This behavior can be controlled by setting navigateBack "false" / false in model config which disables navigation completely.
          */
          navigateBack !== false && handleNavigation();
          resetForm({ values: formik.values});
        })
        .catch((err) => {
          snackbar.showErrorCode(
            ERROR_CODES.AN_ERROR_OCCURRED,
            tTranslate(err?.message, tOpts)
          );
          if (model.reloadOnSave) {
            resetForm();
          }
        })
        .finally(() => {
          setIsLoading(false);
        });
    }
  });

  const handleDiscardChanges = useCallback(() => {
    formik.resetForm();
    setIsDiscardDialogOpen(false);
    if (typeof onCancel === consts.function) {
      onCancel();
    }
    navigateBack !== false && handleNavigation();
  }, [formik, onCancel, navigateBack, handleNavigation]);

  const errorOnLoad = useCallback((error) => {
    setIsLoading(false);
    snackbar.showErrorCode(ERROR_CODES.LOAD_FAILED, tTranslate(error?.message, tOpts));
    handleNavigation();
  }, [snackbar, handleNavigation, tTranslate, tOpts]);

  const setActiveRecord = function ({ id, record, lookups }) {
    const isCopy = idWithOptions.indexOf("-") > -1;
    const isNew = !id || id === "0";
    const pageTitle = isNew ? consts.create : isCopy ? consts.copy : consts.edit;
    const linkColumn = isNew ? "" : record[model.linkColumn];
    const breadcrumbs = [{ text: model.breadCrumbs }, { text: pageTitle }];
    if (isCopy) {
      record[model.linkColumn] = "";
    }
    model.columns.forEach((item) => {
      if (item.skipCopy && isCopy) {
        record[item.field] = "";
      }
    });
    setData(record);
    setLookups(lookups);
    setIsLoading(false);
    if (linkColumn !== "") {
      breadcrumbs.push({ text: linkColumn });
    }
    setPageTitle({
      showBreadcrumbs: true,
      breadcrumbs: breadcrumbs
    });
  };
  const handleFormCancel = useCallback((event) => {
    if (formik.dirty && recordEditable) {
      setIsDiscardDialogOpen(true);
    } else {
      if (typeof onCancel === consts.function) {
        onCancel();
      }
      navigateBack !== false && handleNavigation();
    }
    event.preventDefault();
  }, [formik.dirty, recordEditable, onCancel, navigateBack, handleNavigation]);
  const handleDelete = useCallback(async () => {
    try {
      setIsDeleting(true);
      const response = await deleteRecord({
        id,
        api: api || model.api,
        model
      });
      if (response === true) {
        snackbar.showMessage(tTranslate("Record Deleted Successfully.", tOpts));
        navigateBack !== false && handleNavigation();
      }
    } catch (error) {
      snackbar.showErrorCode(ERROR_CODES.DELETE_FAILED, tTranslate(error?.message, tOpts));
    } finally {
      setIsDeleting(false);
    }
  }, [id, api, model, snackbar, navigateBack, handleNavigation, tTranslate, tOpts]);
  const handleCopy = useCallback(() => {
    const basePath = pathname.substring(0, pathname.lastIndexOf("/") + 1);
    navigate(`${basePath}0-${id}`);
  }, [pathname, id, navigate]);
  const clearError = () => {
    setErrorMessage(null)
    setIsDeleting(false);
  };
  const handleChange = useCallback((e) => {
    const { name, value } = e.target;
    setData({ ...data, [name]: value });
  }, [data]);

  const handleSubmit = useCallback(async (e) => {
    if (e) e.preventDefault();
    if (typeof beforeSubmit === consts.function) {
      await beforeSubmit({ formik , model });
    }
    const errors = await formik.validateForm();
    if (Object.keys(errors).length > 0) {
      formik.setTouched(Object.keys(errors).reduce((acc, key) => {
        acc[key] = true;
        return acc;
      }, {}), false);
    } else {
      formik.handleSubmit();
    }
    const fieldName = model.columns.find((col) => errors[col.field])?.field || Object.keys(errors)[0];
    const errorMessage = errors[fieldName];
    if (errorMessage) {
      snackbar.showError(errorMessage, null, "error");
    }
    const fieldConfig = model.columns.find(
      (column) => column.field === fieldName
    ) || {};
    if (fieldConfig.tab) {
      setActiveStep(Object.keys(model.tabs).indexOf(fieldConfig.tab));
    }
  }, [beforeSubmit, formik, model, snackbar, setActiveStep]);

  const breadcrumbs = [
    { text: tTranslate(formTitle, tOpts) },
    { text: id === "0" ? tTranslate("New", tOpts) : tTranslate("Update", tOpts) }
  ];
  const showRelations = Number(id) !== 0 && Boolean(relations.length);
  const showSaveButton = searchParams.has("showRelation");
  const readOnlyRelations = !recordEditable || data.readOnlyRelations;
  const deleteRecordName = model.linkColumn ? data[model.linkColumn] : undefined;
  const { showPageTitle = true } = model;
  const showCopyButton = showFormActions && canCopy && !isNew;
  const showDeleteButton = showFormActions && canDelete && !isNew;
  const hasFormHeaderActions = showCopyButton || showDeleteButton;
  return (
    <>
      {showPageTitle && (
        <PageTitle
          navigate={navigate}
          title={formTitle}
          showBreadcrumbs={!hideBreadcrumb}
          breadcrumbs={breadcrumbs}
          model={model}
          enableBackButton={navigateBack !== undefined}
        />
      )}
      <ActiveStepContext.Provider value={activeStepContextValue}>
        <Paper sx={{ padding: 2, ...sx }}>
          {isLoading ? (
            <Box sx={{ display: "flex", justifyContent: "center", py: 4 }}>
              <CircularProgress />
            </Box>
          ) : (
          <form>
            <Stack
              direction="row"
              spacing={2}
              justifyContent="flex-end"
              alignItems="center"
              mb={1}
            >
              {showCopyButton && (
                <Button
                  variant="contained"
                  color="primary"
                  onClick={handleCopy}
                >{tTranslate("Copy", tOpts)}</Button>
              )}
              {showDeleteButton && (
                <Button
                  variant="contained"
                  color="error"
                  sx={{ bgcolor: 'error.dark', '&:hover': { bgcolor: 'error.dark' } }}
                  onClick={() => setIsDeleting(true)}
                >{tTranslate("Delete", tOpts)}</Button>
              )}
              {showFormActions && hasFormHeaderActions && (
                <Divider orientation="vertical" flexItem />
              )}
              {canEdit && recordEditable && !showSaveButton && !readOnly && (
                <Button
                  variant="contained"
                  type="submit"
                  color="success"
                  onClick={handleSubmit}
                >{tTranslate("Save", tOpts)}</Button>
              )}
              <Button
                variant="contained"
                type="cancel"
                color="error"
                onClick={handleFormCancel}
              >{tTranslate("Cancel", tOpts)}</Button>
            </Stack>
            <Layout
              model={model}
              formik={formik}
              data={data}
              fieldConfigs={fieldConfigs}
              onChange={handleChange}
              lookups={lookups}
              id={id}
              handleSubmit={handleSubmit}
              mode={mode}
            />
          </form>
          )}
          {errorMessage && (
            <DialogComponent
              open={!!errorMessage}
              onConfirm={clearError}
              onCancel={clearError}
              title="Info"
              hideCancelButton={true}
            >
              {" "}
              {errorMessage}
            </DialogComponent>
          )}
          <DialogComponent
            open={isDiscardDialogOpen}
            onConfirm={handleDiscardChanges}
            onCancel={() => setIsDiscardDialogOpen(false)}
            title={tTranslate("Changes not saved", tOpts)}
            okText={tTranslate("Discard", tOpts)}
            cancelText={tTranslate("Continue", tOpts)}
          >
            {tTranslate("Would you like to continue to edit or discard changes?", tOpts)}
          </DialogComponent>
          <DialogComponent
            open={isDeleting}
            onConfirm={handleDelete}
            onCancel={() => {
              setIsDeleting(false);
              setDeleteError(null);
            }}
            title={deleteError ? tTranslate("Error Deleting Record", tOpts) : tTranslate("Confirm Delete", tOpts)}
          >{deletePromptText ? deletePromptText : (
            <>
              {tTranslate("Are you sure you want to delete", tOpts)}{" "}
              {deleteRecordName && (
                <Tooltip title={deleteRecordName} arrow>
                  <span>{String(deleteRecordName).length > 30 ? `${String(deleteRecordName).slice(0, 30)}...` : deleteRecordName}</span>
                </Tooltip>
              )}
              ?
            </>
          )}</DialogComponent>
          {showRelations ? (
            <Relations
              readOnly={readOnlyRelations}
              models={models}
              relationFilters={relationFilters}
              relations={relations}
              parent={model.name || model.title || ""}
              tTranslate={tTranslate}
              tOpts={tOpts}
            />
          ) : null}
        </Paper>
      </ActiveStepContext.Provider>
    </>
  );
};
export default Form;
