import GridBase from './index';
import * as yup from 'yup';
import { Divider } from '@mui/material';
import Form from '../Form/Form';
import ChildGridTabs from './ChildGridTabs';
import utils from '../utils';

const regexConfig = {
	password: /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,50}$/,
	nonAlphaNumeric: /[^a-zA-Z0-9]/g,
	compareValidatorRegex: /^compare:(.+)$/,
	notEqualValidatorRegex: /^notEqual:([^:]+)(?::(.+))?$/,
	email: /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/
};

const validationMessageTemplates = {
	required: '${label}: required',
	requiredSelectOption: '${label}: select at least one option',
	requiredSelect: '${label}: required',
	minChars: '${label}: minimum ${min} characters',
	maxChars: '${label}: maximum ${max} characters',
	passwordInvalid: '${label}: invalid password',
	passwordPolicy: '${label}: must contain lowercase, uppercase, digit, and special character',
	emailInvalid: '${label}: invalid email format',
	requiredNumber: '${label}: required',
	minNumber: '${label}: minimum value is ${min}',
	maxNumber: '${label}: maximum value is ${max}',
	mustMatch: '${label}: must match ${compareLabel}',
	notEqual: '${label}: must not be the same as ${compareLabel}'
};

const defaultValidationTranslationKeyPrefix = 'validation';

/**
 * Resolves a validation message for a rule.
 *
 * Builds the key `<defaultValidationTranslationKeyPrefix>.<rule>` and looks it
 * up via the provided i18next `t` function with the built-in English template as
 * the `defaultValue`. The resolved string is then processed through `replaceTags`
 * to substitute any `${token}` placeholders from `params`.
 *
 * @param {string} rule Validation rule key (must exist in validationMessageTemplates).
 * @param {Object} params Token map used to format the message (e.g. { label, min, max }).
 * @param {Function} [t] Optional i18next t() function for i18n lookup.
 * @returns {string}
 */
const resolveValidationMessage = (rule, params, t) => {
	const template = validationMessageTemplates[rule];
	const key = `${defaultValidationTranslationKeyPrefix}.${rule}`;
	const translated = typeof t === 'function'
		? t(key, { defaultValue: template })
		: template;
	return utils.replaceTags(translated, params);
};

const emptyToNullTransform = (value, originalValue) => {
	if (originalValue === '' || originalValue === null) return null;
	return value;
};

const isValidNumericValue = (value) => value !== undefined && value !== '' && !isNaN(Number(value));

const applyRequired = (config, label, shouldTrim = false, t) => {
	if (shouldTrim && typeof config.trim === 'function') {
		return config.trim().required(resolveValidationMessage('required', { label }, t));
	}
	return config.required(resolveValidationMessage('required', { label }, t));
};

const customStyle = {};
const showRowsSelected = true;
const defaultValueConfigs = {
	"string": "",
	"boolean": false,
	"radio": false,
	"oneToMany": ""
};

class UiModel {

	static defaultPermissions = {
		add: true,
		edit: true,
		delete: true
	};

	constructor(modelConfig) {
		const { title = "" } = modelConfig;
		let { api, idProperty = api + 'Id' } = modelConfig;
		const module = "module" in modelConfig ? modelConfig.module : title.replace(/[^\w\s]/gi, "");
		if (!api) {
			api = `${title.replaceAll(regexConfig.nonAlphaNumeric, '-').toLowerCase()}`;
			idProperty = title.replaceAll(' ', '') + 'Id';
		}
		const defaultValues = { ...modelConfig.defaultValues };
		const name = module || title;
		Object.assign(this, {
			standard: true,
			name,
			permissions: { ...UiModel.defaultPermissions },
			idProperty,
			linkColumn: `${name}Name`,
			overrideFileName: title,
			preferenceId: name,
			tableName: name,
			module,
			...modelConfig,
			api
		});
		this._applyColumnDefaults();
		this.columnVisibilityModel = this._getColumnVisibilityModel();
		this.defaultValues = this._getDefaultValues(defaultValues);
		this.relationItems = this._resolveRelationItems();
	}

	// `relations.items` lists the child grids shown as tabs below a selected row (Grid/index.js's
	// ChildGrids). Each entry is either a bare model, or an override object `{ model, name, hideColumns,
	// joinColumn, joinColumnAsParam, relationsParam, disableRelations, readOnly }`.
	_resolveRelationItems() {
		const { relations } = this;
		if (!relations || Array.isArray(relations) || !relations.items) return [];
		const sharedHideColumns = relations.hideColumns || [];
		return relations.items.map(item => this._resolveRelationItem(item, sharedHideColumns));
	}

	_resolveRelationItem(item, sharedHideColumns) {
		const { model, name, hideColumns = [], joinColumn, joinColumnAsParam, relationsParam, disableRelations = true, readOnly = true } = 'model' in item ? item : { model: item };
		const hiddenFields = new Set([...sharedHideColumns, ...hideColumns]);
		const needsColumnOverride = hiddenFields.size > 0 || readOnly;

		const overrides = {
			...(name && { name }),
			// readOnly also turns off columns flagged link: true - with Add/Edit/Delete disabled below,
			// such a column would still render as a dead edit-navigation link.
			...(needsColumnOverride && {
				columns: model.columns
					.filter(col => !hiddenFields.has(col.field))
					.map(col => (readOnly && col.link === true) ? { ...col, link: false } : col)
			}),
			...(joinColumn && { joinColumn }),
			...(joinColumnAsParam !== undefined && { joinColumnAsParam }),
			...(relationsParam && { relationsParam }),
			// A relation model (e.g. Asset) may itself declare relations.items for its own use as a
			// top-level grid. disableRelations stops those from being carried into this parent's tab,
			// where they'd render as an unwanted extra level of nested child grids.
			...(disableRelations && { relationItems: [] }),
			// readOnly makes this relation's child grid fully read-only (GridBase's isReadOnly already
			// hides the whole actions column - Edit/Copy/Delete/History/customActions - once
			// model.readOnly is true), drops linkColumn so its name column no longer acts as an
			// edit-navigation link, and hides header filters since there's nothing to edit into a
			// filtered view.
			...(readOnly && { readOnly: true, linkColumn: undefined, showHeaderFilters: false })
		};

		if (!Object.keys(overrides).length) return model;
		return Object.assign(Object.create(Object.getPrototypeOf(model)), model, overrides);
	}

	_applyColumnDefaults() {
		for (const col of this.columns) {
			if (!col.type) {
				col.type = 'string';
			}
		}
	}

	_getColumnVisibilityModel() {
		const columnVisibilityModel = {};
		for (const col of this.columns) {
			if (col.hide === true) {
				columnVisibilityModel[col.id || col.field] = false;
			}
		}
		return columnVisibilityModel;
	}

	_getDefaultValues(defaultValues) {
		for (const col of this.columns) {
			const name = col.field || col.id;
			defaultValues[name] = col.defaultValue === undefined ? (defaultValueConfigs[col.type] || "") : col.defaultValue;
		}
		return defaultValues;
	}

	applyBuiltInValidation(config, validationContext) {
		const { column, columnByField, formLabel, t, tTranslate, tOpts } = validationContext;
		const { validate } = column;
		if (typeof validate !== 'string') {
			return config;
		}
		const compareValidator = regexConfig.compareValidatorRegex.exec(validate);
		const notEqualValidator = regexConfig.notEqualValidatorRegex.exec(validate);
		if (compareValidator) {
			const compareFieldName = compareValidator[1];
			const compareField = columnByField.get(compareFieldName);
			return config.oneOf(
				[yup.ref(compareFieldName)],
				resolveValidationMessage('mustMatch', { label: formLabel, compareLabel: tTranslate(compareField?.label || compareFieldName, tOpts) }, t)
			);
		}
		if (notEqualValidator) {
			const [, compareFieldName, compareLabelOverride] = notEqualValidator;
			const compareLabel = tTranslate(compareLabelOverride || columnByField.get(compareFieldName)?.label || compareFieldName, tOpts);
			const treatZeroAsEmpty = typeof column.treatZeroAsEmpty === 'boolean' ? column.treatZeroAsEmpty : !!column.lookup;
			return config.test(
				'not-equal',
				resolveValidationMessage('notEqual', { label: formLabel, compareLabel }, t),
				function (value) {
					const compareValue = this.parent?.[compareFieldName];
					const isEmpty = (v) => v === undefined || v === null || v === '' || (treatZeroAsEmpty && (v === 0 || v === '0'));
					if (isEmpty(value) || isEmpty(compareValue)) return true;
					return String(value) !== String(compareValue);
				}
			);
		}
		return config;
	}

	applyCustomValidation(config, _validationContext) {
		return config;
	}

	applyColumnValidation(config, validationContext) {
		const { column } = validationContext;
		const { validate } = column;

		let nextConfig = config;

		if (typeof validate === 'function') {
			nextConfig = validate.call(this, nextConfig, validationContext);
		} else {
			nextConfig = this.applyBuiltInValidation(nextConfig, validationContext);
		}

		return this.applyCustomValidation(nextConfig, validationContext);
	}

	getValidationSchema({ id, tTranslate = (key) => key, tOpts = {} } = {}) {
		const { columns } = this;
		const t = tOpts?.t;
		const validationConfig = {};
		const columnByField = new Map(columns.flatMap(col => {
			const entries = [[col.field, col]];
			if (col.formField) entries.push([col.formField, col]);
			return entries;
		}));
		if (this.title && this.idProperty && !columnByField.has(this.idProperty)) {
			columnByField.set(this.idProperty, { field: this.idProperty, label: this.title });
		}
		for (const column of columns) {
			const { field, label, header, type = 'string', requiredIfNew = false, required = false, min = '', max = '' } = column;
			const formLabel = tTranslate(label || header || field, tOpts);
			if (!formLabel) {
				continue;
			}
			if (label === null || label === '') continue; // Skip fields that should not be validated in form mode
			let config;
			switch (type) {
				case 'string':
					config = yup.string().nullable().trim().label(formLabel);
					if (isValidNumericValue(min)) {
						config = config.min(Number(min), resolveValidationMessage('minChars', { label: formLabel, min }, t));
					}
					if (isValidNumericValue(max)) {
						config = config.max(Number(max), resolveValidationMessage('maxChars', { label: formLabel, max }, t));
					}
					break;
				case 'boolean':
					config = yup.bool().nullable().transform(emptyToNullTransform).label(formLabel);
					break;
				case 'radio':
				case 'dayRadio':
					config = yup.mixed().label(formLabel).nullable();
					break;
				case 'date':
					config = yup.date().nullable().transform(emptyToNullTransform).label(formLabel);
					break;
				case 'dateTime':
					config = yup
						.date()
						.nullable()
						.transform(emptyToNullTransform)
						.label(formLabel);
					break;
				case 'select':
					config = yup.string().transform((value, originalValue) => {
						if (originalValue === 0 || originalValue === '0') return '';
						return value;
					}).trim().label(formLabel);
					if (!required) {
						config = config.nullable();
					}
					break;
				case 'autocomplete':
					config = yup.string().trim().label(formLabel);
					if (!required) {
						config = config.nullable();
					}
					break;
				case 'password':
					config = yup.string()
						.label(formLabel)
						.test("ignore-asterisks", resolveValidationMessage('passwordInvalid', { label: formLabel }, t), (value) => {
							// Skip further validations if value is exactly "******"
							if (value === "******") return true;
							const minlength = Number(min) || 8;
							const maxlength = Number(max) || 50;
							const regex = column.regex || regexConfig.password;
							// Check minimum length, maximum length, and pattern if not "******"
							return yup.string()
								.min(minlength, resolveValidationMessage('minChars', { label: formLabel, min: minlength }, t))
								.max(maxlength, resolveValidationMessage('maxChars', { label: formLabel, max: maxlength }, t))
								.matches(
									regex,
									resolveValidationMessage('passwordPolicy', { label: formLabel }, t)
								)
								.isValidSync(value);
						});
					break;
				case 'email':
					config = yup
						.string()
						.trim()
						.matches(
							(column.regex || regexConfig.email),
							resolveValidationMessage('emailInvalid', { label: formLabel }, t)
						);
					break;
				case 'number':
					config = yup.number().nullable().transform(emptyToNullTransform).label(formLabel);
					if (isValidNumericValue(min)) {
						config = config.min(Number(min), resolveValidationMessage('minNumber', { label: formLabel, min }, t));
					}
					if (isValidNumericValue(max)) {
						config = config.max(Number(max), resolveValidationMessage('maxNumber', { label: formLabel, max }, t));
					}
					break;
				case 'fileUpload':
					config = yup.string().trim().label(formLabel);
					break;
				default:
					config = yup.mixed().nullable().label(formLabel);
					break;
			}

			// Apply required/requiredIfNew logic in one place
			if (required) {
				if (type === 'string') {
					config = applyRequired(config, formLabel, true, t);
				} else if (type === 'radio' || type === 'dayRadio') {
					config = config.required(resolveValidationMessage('requiredSelectOption', { label: formLabel }, t));
				} else if (type === 'date' || type === 'dateTime') {
					config = config.required(resolveValidationMessage('required', { label: formLabel }, t));
				} else if (type === 'select' || type === 'autocomplete') {
					config = config.required(resolveValidationMessage('requiredSelect', { label: formLabel }, t));
				} else if (type === 'number') {
					config = config.required(resolveValidationMessage('requiredNumber', { label: formLabel }, t));
				} else {
					config = applyRequired(config, formLabel, false, t);
				}
			}
			if (requiredIfNew && (!id || id === '')) {
				config = applyRequired(config, formLabel, type === 'string', t);
			}
			config = this.applyColumnValidation(config, {
				column,
				columnByField,
				formLabel,
				id,
				resolveValidationMessage,
				t,
				tOpts,
				tTranslate,
				yup
			});

			validationConfig[field] = config;
		}

		return yup.object({ ...validationConfig, ...this.validationSchema });
	}

	Form = ({ ...props }) => {
		return <Form model={this} Layout={this.Layout} {...props} />;
	};

	Grid = ({ ...props }) => {
		return <GridBase model={this} showRowsSelected={showRowsSelected} {...props} />;
	};
	ChildGrid = (props) => {
		return <>
			<GridBase model={this} {...props} customStyle={customStyle} showRowsSelected={showRowsSelected} />
			<Divider orientation='horizontal' sx={{ mt: 2 }} />
		</>;
	};

	// Renders this model's declared relations.items (resolved into this.relationItems) as the child
	// grid tabs shown below the parent grid. Form pages use Form/relations' Relations instead.
	ChildGrids = (props) => {
		if (!this.relationItems?.length) return null;
		const relations = this.relationItems.map(childModel => childModel.name);
		return <ChildGridTabs relations={relations} models={this.relationItems} {...props} />;
	};
}

export {
	UiModel
};
