import { useMemo, useState } from 'react';
import CloseIcon from '@mui/icons-material/Close';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import SaveIcon from '@mui/icons-material/Save';
import SettingsIcon from '@mui/icons-material/Settings';
import RefreshIcon from '@mui/icons-material/Refresh';
import AddIcon from '@mui/icons-material/Add';
import { Box, Button, Checkbox, FormControlLabel, Grid, List, ListItem, ListItemButton, ListItemText, Menu, MenuItem, Stack, TextField, Typography, Tooltip, ListItemIcon } from '@mui/material';
import { DataGridPremium, GridActionsCellItem, useGridApiRef } from '@mui/x-data-grid-premium';
import { useFormik } from 'formik';
import * as yup from 'yup';
import { useSnackbar } from '../SnackBar';
import request, { DATA_PARSERS } from './httpRequest';
import { parsePreferenceState } from './useGridPreferences';
import { useStateContext } from '../useRouter/StateProvider';
import { DialogComponent } from '../Dialog';

const actionTypes = {
    Edit: "Edit",
    Delete: "Delete"
};

const DIALOG_TYPES = {
    ADD: "Add",
    EDIT: "Edit",
    MANAGE: "Manage",
    NONE: null
};

const initialValues = {
    prefName: '',
    prefDesc: '',
    isDefault: false
};

const paginationModel = { pageSize: 50, page: 0 };

const pageSizeOptions = [5, 10, 20, 50, 100];

const GridPreferences = ({ gridRef, preferenceKey, preferences, reloadPreferences, onPreferenceChange, onResetToDefault, currentPreference, hasRestoredListState, t, tOpts }) => {
    const { getApiEndpoint } = useStateContext();
    const preferenceApi = getApiEndpoint("GridPreferenceManager");
    const apiRef = useGridApiRef();
    const snackbar = useSnackbar();
    const [dialogState, setDialogState] = useState(DIALOG_TYPES.NONE);
    const [menuAnchorEl, setMenuAnchorEl] = useState(null);
    const [openPreferenceExistsModal, setOpenPreferenceExistsModal] = useState(false);
    const [openConfirmDeleteDialog, setOpenConfirmDeleteDialog] = useState({});

    const gridColumns = useMemo(() => [
        { field: "prefName", type: 'string', width: 300, headerName: t("Preference Name", tOpts), sortable: false, filterable: false },
        { field: "prefDesc", type: 'string', width: 300, headerName: t("Preference Description", tOpts), sortable: false, filterable: false },
        { field: "isDefault", type: "boolean", width: 100, headerName: t("Default", tOpts), sortable: false, filterable: false },
        { field: 'editAction', type: 'actions', headerName: '', width: 20, getActions: () => [<GridActionsCellItem key={1} icon={<Tooltip title={actionTypes.Edit}><EditIcon /></Tooltip>} tabIndex={0} data-action={actionTypes.Edit} label={t("Edit", tOpts)} color="primary" />] },
        { field: 'deleteAction', type: 'actions', headerName: '', width: 20, getActions: () => [<GridActionsCellItem key={2} icon={<Tooltip title={actionTypes.Delete}><DeleteIcon /></Tooltip>} tabIndex={0} data-action={actionTypes.Delete} label={t("Delete", tOpts)} color="error" />] }
    ], [t, tOpts]);

    const validationSchema = useMemo(() =>
        yup.object({
            prefName: yup.string().trim(true).required(t('Preference Name is Required', tOpts)).max(20, t('Maximum Length is ', tOpts) + '20'),
            prefDesc: yup.string().max(100, t('Maximum Length is ', tOpts) + '100')
        }), [t, tOpts]);

    const handleOpen = (event) => setMenuAnchorEl(event?.currentTarget);
    const handleClose = () => setMenuAnchorEl(null);
    const handleDialogClose = () => {
        setDialogState(DIALOG_TYPES.NONE);
        handleClose();
    };

    const resetToDefault = () => {
        onResetToDefault();
        handleClose();
    };

    const applyPreference = (preference) => {
        if (!preference?.prefValue) {
            snackbar.showMessage(t('Failed to load preference.', tOpts));
            return false;
        }

        try {
            onPreferenceChange(preference.prefName, parsePreferenceState(preference.prefValue));
        } catch {
            snackbar.showMessage(t('Failed to parse preference data.', tOpts));
            return false;
        }

        handleClose();
        return true;
    };

    const savePreference = async (values) => {
        const prefName = values.prefName.trim();
        const caseInsensitivePrefName = prefName.toLocaleLowerCase();

        if (preferences.find(ele => ele.prefName.toLocaleLowerCase() === caseInsensitivePrefName && ele.prefId !== values.prefId)) {
            setOpenPreferenceExistsModal(true);
            return;
        }

        const response = await request({ 
            url: preferenceApi, 
            params: {
                action: 'save',
                id: preferenceKey,
                prefId: values.prefId,
                prefName,
                prefDesc: values.prefDesc,
                prefValue: JSON.stringify(gridRef.current.exportState()),
                isDefault: values.isDefault
            },
            dataParser: DATA_PARSERS.json 
        });

        if (response === true || response?.success === true) {
            snackbar.showMessage(t(`Preference ${dialogState === DIALOG_TYPES.ADD ? "added" : "saved"} successfully.`, tOpts));
            handleDialogClose();
            if (dialogState === DIALOG_TYPES.EDIT && preferences.find(pref => pref.prefId === values.prefId)?.prefName === currentPreference) {
                onPreferenceChange(prefName);
            }
            await reloadPreferences();
            return;
        }

        snackbar.showMessage(t('Error saving preference: ', tOpts) + (response?.message || t('Unknown error', tOpts)));
    };

    const deletePreference = async () => {
        const response = await request({ 
            url: preferenceApi, 
            params: {
                action: 'delete',
                id: preferenceKey,
                prefIdArray: openConfirmDeleteDialog.prefId
            },
            dataParser: DATA_PARSERS.json 
        });

        if (response === true || response?.success === true) {
            snackbar.showMessage(t('Preference deleted successfully.', tOpts));
            if (openConfirmDeleteDialog.preferenceName === currentPreference) onPreferenceChange(null);
            await reloadPreferences();
            setOpenConfirmDeleteDialog({});
            return;
        }

        snackbar.showMessage(t('Error deleting preference: ', tOpts) + (response?.message || t('Unknown error', tOpts)));
    };

    const onCellClick = (cellParams) => {
        const action = cellParams.field === 'editAction' ? actionTypes.Edit : cellParams.field === 'deleteAction' ? actionTypes.Delete : null;
        if (cellParams.id === 0 && action) {
            snackbar.showMessage(t(`Default preference cannot be ${action === actionTypes.Edit ? 'edited' : 'deleted'}`, tOpts));
            return;
        }
        if (action === actionTypes.Edit) {
            setDialogState(DIALOG_TYPES.EDIT);
            formik.setValues(cellParams?.row);
        }
        if (action === actionTypes.Delete) {
            setOpenConfirmDeleteDialog({
                prefId: cellParams.row.prefId,
                preferenceName: cellParams.row.prefName
            });
        }
    };

    const openDialog = (type) => {
        setDialogState(type);
        handleClose();
        if (type === DIALOG_TYPES.ADD) {
            formik.resetForm();
        }
    };

    const formik = useFormik({
        initialValues,
        validationSchema,
        onSubmit: savePreference,
        mode: "onBlur"
    });

    // Memoize locale text used by the DataGrid to avoid recreating the object on every render
    const localeText = useMemo(() => ({
        noRowsLabel: t("No rows", tOpts),
        columnMenuManageColumns: t('Manage columns', tOpts),
        columnMenuHideColumn: t('Hide column', tOpts),
        pinToLeft: t('Pin to left', tOpts),
        pinToRight: t('Pin to right', tOpts),
        columnMenuLabel: t('Menu', tOpts),
        filterPanelRemoveAll: t('Remove all', tOpts),
        columnsPanelTextFieldLabel: t('Find column', tOpts),
        columnsPanelTextFieldPlaceholder: t('Column title', tOpts),
        columnsPanelShowAllButton: t('Show all', tOpts),
        columnsPanelHideAllButton: t('Hide all', tOpts),
        booleanCellTrueLabel: t('Yes', tOpts),
        toolbarColumnsLabel: t('Select columns', tOpts),
        toolbarExportLabel: t('Export', tOpts),
        booleanCellFalseLabel: t('No', tOpts),
        paginationRowsPerPage: t('Rows per page', tOpts),
        paginationDisplayedRows: ({ from, to, count }) => `${from}–${to} ${t('of', tOpts)} ${count}`,
        toolbarQuickFilterLabel: t('Search', tOpts),
        columnsManagementSearchTitle: t('Search', tOpts),
        columnsManagementNoColumns: t('No columns', tOpts)
    }), [t, tOpts]);

    const isManageDialog = dialogState === DIALOG_TYPES.MANAGE;
    const isFormDialog = dialogState === DIALOG_TYPES.ADD || dialogState === DIALOG_TYPES.EDIT;
    // There is nothing to reset on a plain first load - the grid is already showing model defaults - so the entry only appears once a preference is applied or a restored snapshot is in effect.
    const canResetToDefault = !!currentPreference || hasRestoredListState;

    return (
        <Box>
            <Button
                id="grid-preferences-btn"
                aria-controls={menuAnchorEl ? 'basic-menu' : undefined}
                aria-haspopup="true"
                aria-expanded={menuAnchorEl ? 'true' : undefined}
                onClick={handleOpen}
                disabled={preferences === null}
                title={t('Preference', tOpts)}
                startIcon={<SettingsIcon />}
                size="small"
                variant="text"
            >
                {t('Preferences', tOpts)} {currentPreference && `(${currentPreference})`}
            </Button>
            <Menu
                id={`grid-preference-menu`}
                anchorEl={menuAnchorEl}
                open={!!menuAnchorEl}
                onClose={handleClose}
                component={List}
                dense
                MenuListProps={{
                    'aria-labelledby': 'grid-preferences-btn'
                }}
                sx={{
                    '& .MuiMenu-paper': { minWidth: 240, maxHeight: 320 },
                    '& .MuiListItemSecondaryAction-root': {
                        display: 'flex'
                    },
                    '& .Mui-selected': {
                        color: 'text.primary',
                        '&:hover': {
                            backgroundColor: 'success.main'
                        }
                    }
                }}
            >
                <MenuItem component={ListItemButton} dense onClick={() => openDialog(DIALOG_TYPES.ADD)}>
                    <ListItemIcon>
                        <AddIcon />
                    </ListItemIcon>
                    {t('Add Preference', tOpts)}
                </MenuItem>
                <MenuItem component={ListItemButton} dense divider={!canResetToDefault && preferences?.length > 0} onClick={() => openDialog(DIALOG_TYPES.MANAGE)}>
                    <ListItemIcon>
                        <SettingsIcon />
                    </ListItemIcon>
                    {t('Manage Preferences', tOpts)}
                </MenuItem>
                {canResetToDefault && (
                    <MenuItem component={ListItemButton} dense divider={preferences?.length > 0} onClick={resetToDefault}>
                        <ListItemIcon>
                            <RefreshIcon />
                        </ListItemIcon>
                        {t('Reset to Default', tOpts)}
                    </MenuItem>
                )}

                {preferences?.length > 0 && preferences?.map((ele) => {
                    const { prefName, prefDesc, prefId } = ele;
                    return (
                        <MenuItem
                            onClick={() => applyPreference(ele)}
                            component={ListItem}
                            selected={currentPreference === prefName}
                            key={`pref-item-${prefId}`}
                            title={t(prefDesc, tOpts)}
                            dense
                        >
                            <ListItemText primary={prefName} />
                        </MenuItem>
                    );
                })}
            </Menu>
            <DialogComponent
                open={dialogState !== DIALOG_TYPES.NONE}
                disableRestoreFocus
                title={
                    <Typography variant="h5" component="span">
                        {dialogState} {t(isManageDialog ? 'Preferences' : 'Preference', tOpts)}
                    </Typography>
                }
                maxWidth={isManageDialog ? 'md' : 'sm'}
                fullWidth
            >
                {isFormDialog && (
                    <Grid
                        component={'form'}
                        onSubmit={formik.handleSubmit}
                        rowGap={2}
                        container
                        sx={{
                            '& .MuiFormLabel-root:not(.MuiTypography-root)': {
                                fontWeight: 400,
                                display: 'table',
                                whiteSpace: 'pre-wrap' /* css-3 */,
                                wordWrap: 'break-word' /* Internet Explorer 5.5+ */
                            }
                        }}
                    >
                        <Grid size={12}>
                            <TextField
                                value={formik.values.prefName}
                                variant="outlined"
                                size="small"
                                margin="dense"
                                label={
                                    <span>
                                        {t('Preference Name', tOpts)} <span style={{ color: 'red' }}>*</span>
                                    </span>
                                }
                                autoFocus
                                name="prefName"
                                onChange={formik.handleChange}
                                error={!!formik.errors.prefName}
                                helperText={formik.errors.prefName}
                                fullWidth
                            />
                        </Grid>
                        <Grid size={12}>
                            <TextField
                                value={formik.values.prefDesc}
                                variant="outlined"
                                multiline
                                rows={2}
                                size="small"
                                margin="dense"
                                label={t('Preference Description', tOpts)}
                                name="prefDesc"
                                onChange={formik.handleChange}
                                error={!!formik.errors.prefDesc}
                                helperText={formik.errors.prefDesc}
                                fullWidth
                            />
                        </Grid>
                        <Grid size={12}>
                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={formik.values.isDefault}
                                        name="isDefault"
                                        onChange={formik.handleChange}
                                    />
                                }
                                label={t('Default', tOpts)}
                            />
                        </Grid>
                        <Grid size={12}>
                            <Stack direction="row" columnGap={1} style={{ justifyContent: 'end' }}>
                                <Button
                                    type="submit"
                                    size="small"
                                    startIcon={<SaveIcon />}
                                    color="primary"
                                    variant="contained"
                                    disableElevation
                                >
                                    {t('Save', tOpts)}
                                </Button>
                                <Button
                                    type="button"
                                    startIcon={<CloseIcon />}
                                    color="error"
                                    variant="contained"
                                    size="small"
                                    onClick={handleDialogClose}
                                    disableElevation
                                >
                                    {t('Close', tOpts)}
                                </Button>
                            </Stack>
                        </Grid>
                    </Grid>
                )}

                {isManageDialog && (
                    <Grid container rowGap={2}>
                        <Grid size={12}>
                            <DataGridPremium
                                sx={{
                                    "& .MuiTablePagination-selectLabel": {
                                        marginTop: 2
                                    },
                                    "& .MuiTablePagination-displayedRows": {
                                        marginTop: 2
                                    },
                                    "& .MuiDataGrid-columnHeader .MuiInputLabel-shrink": {
                                        display: "none"
                                    }
                                }}
                                className="pagination-fix"
                                onCellClick={onCellClick}
                                columns={gridColumns}
                                pageSizeOptions={pageSizeOptions}
                                pagination
                                rowCount={preferences.length}
                                rows={preferences}
                                getRowId={(row) => row.prefId}
                                slots={{
                                    headerFilterMenu: false
                                }}
                                density="compact"
                                disableDensitySelector={true}
                                apiRef={apiRef}
                                disableAggregation={true}
                                disableRowGrouping={true}
                                disableRowSelectionOnClick={true}
                                initialState={{
                                    pagination: {
                                        paginationModel
                                    }
                                }}
                                localeText={localeText}
                            />
                        </Grid>
                        <Grid size={12}>
                            <Stack direction="row" columnGap={1} style={{ justifyContent: 'end' }}>
                                <Button
                                    type="button"
                                    startIcon={<CloseIcon />}
                                    color="error"
                                    variant="contained"
                                    size="small"
                                    onClick={handleDialogClose}
                                    disableElevation
                                >
                                    {t('Close', tOpts)}
                                </Button>
                            </Stack>
                        </Grid>
                    </Grid>
                )}
            </DialogComponent>
            <DialogComponent
                open={openPreferenceExistsModal}
                onConfirm={() => setOpenPreferenceExistsModal(false)}
                title=""
                okText={t('Ok', tOpts)}
                cancelText=""
            >
                "{formik.values.prefName.trim()}": {t('name already in use, please use another name.', tOpts)}
            </DialogComponent>
            <DialogComponent
                open={!!openConfirmDeleteDialog.preferenceName}
                onConfirm={deletePreference}
                onCancel={() => setOpenConfirmDeleteDialog({})}
                title={t('Confirm delete', tOpts)}
                yesNo={true}
            >
                {t('Are you sure you wish to delete', tOpts)} "{openConfirmDeleteDialog.preferenceName}"?
            </DialogComponent>
        </Box>
    );
};

export default GridPreferences;
